<div class="grid cards"><?php foreach([["Connected Channels",$stats['channels']],["Pending / Scheduled",$stats['pending']],["Uploaded",$stats['uploaded']],["Failed",$stats['failed']],["Today's Uploads",$stats['today']]] as $s):?><div class="card"><div class="muted"><?=e($s[0])?></div><div class="metric"><?=e((string)$s[1])?></div></div><?php endforeach;?></div><div class="grid two"><div class="card"><h2>Next scheduled upload</h2><?php if($next):?><b><?=e($next['channel_name'])?></b><p><?=e($next['title'])?></p><p class="muted"><?=e($next['scheduled_at'])?> UTC</p><?php else:?><p class="muted">No scheduled uploads.</p><?php endif;?></div><div class="card"><h2>Per-channel statistics</h2><table><tr><th>Channel</th><th>Pending</th><th>Uploaded</th><th>Failed</th></tr><?php foreach($channels as $c):$q=$db->one("SELECT SUM(status IN ('Pending','Queued','Scheduled','Retry')) p,SUM(status='Uploaded') u,SUM(status='Failed') f FROM videos WHERE youtube_channel_id=?",[$c['id']]);?><tr><td><?=e($c['channel_name'])?></td><td><?=e((string)($q['p']??0))?></td><td><?=e((string)($q['u']??0))?></td><td><?=e((string)($q['f']??0))?></td></tr><?php endforeach;?></table></div></div>
